INSERT INTO `rule` (`idRule`, `kriteriaTerpilih`, `idUkm`, `alasan`, `opsi`, `alasanOpsi`) VALUES
('R1', 'K2,K4,K7', 'UKM1', 'Minat yang tinggi menjadi faktor utama karena UKM MADDA menuntut konsistensi, kreativitas, dan kemauan belajar dalam bidang desain grafis, fotografi, videografi, editing dan jurnalis. Kemampuan dasar editing memudahkan proses pelatihan dan pengembangan skill, sehingga anggota dapat langsung berkontribusi dalam kegiatan dan proyek UKM. Kreativitas sangat penting dalam menghasilkan konten visual yang menarik, inovatif, dan sesuai dengan kebutuhan publikasi serta branding UKM', NULL, NULL),
('R10', 'K2,K4,K5', 'UKM1', 'Minat yang tinggi menjadi faktor utama karena UKM Multimedia menuntut konsistensi, kreativitas, dan kemauan belajar dalam bidang desain grafis, fotografi, videografi, editing dan jurnalis. Kemampuan dasar editing memudahkan proses pelatihan dan pengembangan skill, sehingga anggota dapat langsung berkontribusi dalam kegiatan dan proyek UKM', NULL, NULL),
('R100', 'K4,K5,K7', 'UKM1', 'Kemampuan dasar editing memudahkan proses pelatihan dan pengembangan skill, sehingga anggota dapat langsung berkontribusi dalam kegiatan dan proyek UKM. Kreativitas sangat penting dalam menghasilkan konten visual yang menarik, inovatif, dan sesuai dengan kebutuhan publikasi serta branding UKM.', NULL, NULL),
('R1000', 'K12,K15,K3,K4', 'UKM3', 'Minat terhadap kewirausahaan berbasis teknologi dan nilai-nilai santri menjadi faktor utama agar anggota memiliki motivasi tinggi dalam mengembangkan usaha yang kreatif, inovatif, dan beretika. Nilai akhlak dan etika santri menjadi dasar dalam menjalankan usaha yang jujur, amanah, dan bertanggung jawab sesuai prinsip kewirausahaan islami.', NULL, ''),
('R1001', 'K14,K3,K4,K8', 'UKM3', 'Minat terhadap kewirausahaan berbasis teknologi dan nilai-nilai santri menjadi faktor utama agar anggota memiliki motivasi tinggi dalam mengembangkan usaha yang kreatif, inovatif, dan beretika. Penguasaan atau ketertarikan pada teknologi sangat penting untuk mendukung pemasaran digital, pengelolaan usaha, dan inovasi produk sesuai konsep technosantri. Asset pendukung seperti media promosi, atau relasi usaha dapat membantu pengembangan kegiatan kewirausahaan anggota UKM.', NULL, ''),
